<?php
$columns=['record_date TEXT NULL','birth_date TEXT NULL','phone1 VARCHAR(50) NULL','phone2 VARCHAR(50) NULL','address TEXT NULL','rating INTEGER NULL','last_name TEXT NULL','unit_code VARCHAR(50) NULL','marriage_date TEXT NULL','age INTEGER NULL','title VARCHAR(150) NULL','branch VARCHAR(150) NULL','email VARCHAR(190) NULL','gender VARCHAR(20) NULL','special_day TEXT NULL','action_name VARCHAR(150) NULL','action_date TEXT NULL','city VARCHAR(100) NULL','district VARCHAR(100) NULL','related_cards TEXT NULL','note TEXT NULL'];
foreach($columns as $definition){$column=explode(' ',$definition)[0];try{if($sqlite){$c=$pdo->query('PRAGMA table_info(units)')->fetchAll();if(!in_array($column,array_column($c,'name'),true))$pdo->exec('ALTER TABLE units ADD COLUMN '.$definition);}else{$q=$pdo->prepare("SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='units' AND column_name=?");$q->execute([$column]);if(!$q->fetchColumn())$pdo->exec('ALTER TABLE units ADD COLUMN '.$definition);}}catch(Throwable $e){}}
$message='';$error='';$editId=(int)($_GET['edit']??0);$unit=null;if($editId){$s=$pdo->prepare('SELECT * FROM units WHERE id=?');$s->execute([$editId]);$unit=$s->fetch()?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);try{if($action==='delete'){$pdo->prepare('DELETE FROM units WHERE id=?')->execute([$id]);$message='Ünite silindi.';}else{$f=['record_date','name','last_name','birth_date','age','marriage_date','title','branch','rating','email','phone1','phone2','gender','special_day','action_name','action_date','city','district','related_cards','address','note'];$v=[];foreach($f as $x)$v[]=trim((string)($_POST[$x]??''));if($v[1]==='')throw new RuntimeException('Ad zorunludur.');if($action==='update'){$v[]=$id;$pdo->prepare('UPDATE units SET record_date=?,name=?,last_name=?,birth_date=?,age=?,marriage_date=?,title=?,branch=?,rating=?,email=?,phone1=?,phone2=?,gender=?,special_day=?,action_name=?,action_date=?,city=?,district=?,related_cards=?,address=?,note=? WHERE id=?')->execute($v);$message='Ünite güncellendi.';}else{$code='U'.date('ymd').random_int(100,999);array_unshift($v,$code);$pdo->prepare('INSERT INTO units(code,record_date,name,last_name,birth_date,age,marriage_date,title,branch,rating,email,phone1,phone2,gender,special_day,action_name,action_date,city,district,related_cards,address,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($v);$message='Ünite kaydedildi.';}}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Kayıt işlemi tamamlanamadı.';}}
$units=$pdo->query('SELECT * FROM units ORDER BY name,last_name')->fetchAll();patient_header('Üniteler','cash');function uv($key,$default=''){global $unit;return e($unit[$key]??$default);}?>
<main class="patient-container uv"><h1>Üniteler</h1><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif?><section><header><h2>Ünite Listesi</h2><details <?=$unit?'open':''?>><summary><?=$unit?'Üniteyi Düzenle':'Yeni Ünite Ekle'?></summary><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="<?=$unit?'update':'save'?>"><?php if($unit):?><input type="hidden" name="id" value="<?=(int)$unit['id']?>"><?php endif?><label>Kayıt No<input value="<?=$unit?uv('code'):'Otomatik'?>" readonly></label><label>Kayıt Tarihi<input type="date" name="record_date" value="<?=uv('record_date',date('Y-m-d'))?>"></label><label>Ad<input name="name" value="<?=uv('name')?>" required></label><label>Soyad<input name="last_name" value="<?=uv('last_name')?>"></label><label>Doğum Tarihi<input type="date" name="birth_date" value="<?=uv('birth_date')?>"></label><label>Yaş<input type="number" name="age" value="<?=uv('age')?>"></label><label>Evlilik Tarihi<input type="date" name="marriage_date" value="<?=uv('marriage_date')?>"></label><label>Ünvan<input name="title" value="<?=uv('title')?>"></label><label>Branş<input name="branch" value="<?=uv('branch')?>"></label><label>Yıldız<input type="number" min="1" max="5" name="rating" value="<?=uv('rating','1')?>"></label><label>Email<input type="email" name="email" value="<?=uv('email')?>"></label><label>Telefon 1<input name="phone1" value="<?=uv('phone1')?>"></label><label>Telefon 2<input name="phone2" value="<?=uv('phone2')?>"></label><label>Cinsiyet<select name="gender"><option>Erkek</option><option>Kadın</option></select></label><label>Özel Gün<input type="date" name="special_day" value="<?=uv('special_day')?>"></label><label>Aksiyon<input name="action_name" value="<?=uv('action_name')?>"></label><label>Aksiyon Tarihi<input type="date" name="action_date" value="<?=uv('action_date')?>"></label><label>Şehir<input name="city" value="<?=uv('city')?>"></label><label>İlçe<input name="district" value="<?=uv('district')?>"></label><label class="wide">İlişkili Kartlar<input name="related_cards" value="<?=uv('related_cards')?>"></label><label class="wide">Adres<textarea name="address"><?=uv('address')?></textarea></label><label class="wide">Not<textarea name="note"><?=uv('note')?></textarea></label><button class="save" title="Kaydet"><i class="ti tabler-device-floppy"></i></button></form></details></header><table><tr><th>KAYIT NO</th><th>AD SOYAD</th><th>TELEFON</th><th>İŞLEMLER</th></tr><?php foreach($units as $u):?><tr><td><?=e($u['code'])?></td><td><?=e($u['name'].' '.$u['last_name'])?></td><td><?=e($u['phone1'])?></td><td><a href="<?=url('units.php?edit='.(int)$u['id'])?>">✎</a></td></tr><?php endforeach?></table></section></main><style>.uv{max-width:1180px!important;padding:96px 32px!important}.uv section{padding:20px;border:1px solid var(--line);border-radius:8px;background:var(--card)}.uv header{display:flex;justify-content:space-between}.uv summary{cursor:pointer}.uv details[open]{position:fixed;inset:64px 0 0 260px;z-index:50;overflow:auto;padding:36px;background:#f7f7fb}.uv form{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:1036px;margin:auto}.uv label{display:flex;flex-direction:column;gap:5px}.uv input,.uv select,.uv textarea{padding:9px;border:1px solid #d2d2dc;border-radius:5px;font:inherit}.uv textarea{height:72px}.uv .wide{grid-column:1/-1}.uv .save{width:42px;height:42px;border:0;border-radius:7px;background:#19a94b;color:#fff}.uv table{width:100%;margin-top:18px;border-collapse:collapse}.uv th,.uv td{padding:12px;border-bottom:1px solid var(--line);text-align:left}.ok{color:#16883d}@media(max-width:700px){.uv{padding:92px 14px!important}.uv details[open]{left:0;padding:20px}.uv form{grid-template-columns:1fr}}</style><?php patient_footer();?>
